// Read-only team readiness: current source-backed roles, no approval or execution command.
let teamApprovalQueue=null,teamApprovalQueueGeneration=0,teamApprovalDetailGeneration=0,teamApprovalLock=null;
const teamApprovalIssues={CURRENT_MENTOR_ACCEPTANCE_REQUIRED:'A current mentor must accept the assignment.',FINAL_AUTHORITY_UNAVAILABLE:'The configured final approval authority is unavailable.',CONSULTATION_SCOPE_UNCONFIRMED:'The Research Coordinator needs to confirm the overall consultation scope.',CONSULTATION_RESPONSES_REQUIRE_REVIEW:'Consultation requests remain pending, declined, withdrawn or require fresh review.'};
const teamApprovalMentors={MISSING:'Not assigned',REQUESTED:'Awaiting acceptance',ACCEPTED:'Accepted',REASSIGNMENT_REQUESTED:'Reassignment requested',WITHDRAWN:'Withdrawn',STALE:'Source changed — review required'};
const teamApprovalStates={REVIEW_REQUIRED:'Review required',READY_FOR_FINAL_REVIEW:'Ready for final review',FINAL_APPROVED:'Final approval recorded',FINAL_REJECTED:'Final rejection recorded'};
function cleanTeamFinalDecision(v){const d=v.finalDecision;if(d===undefined)return null;if(!d||typeof d.id!=='string'||!/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(d.id)||!Number.isSafeInteger(d.version)||d.version<1||!['APPROVED','REJECTED'].includes(d.decision)||typeof d.reason!=='string'||!d.reason.trim()||d.reason.length>2000)throw Error('Final review record changed.');return d}
function teamApprovalItem(v){const id=x=>typeof x==='string'&&/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(x);if(!v||!id(v.proposalId)||!id(v.firstReviewId)||!v.firstReviewId.startsWith(v.proposalId+':first-review:')||!Number.isSafeInteger(v.submissionVersion)||v.submissionVersion<1||typeof v.title!=='string'||v.title.length>120||!Array.isArray(v.roles)||!v.roles.length||v.roles.length>2||new Set(v.roles).size!==v.roles.length||!v.roles.every(r=>['COORDINATOR','FINAL_APPROVER'].includes(r))||!Object.hasOwn(teamApprovalStates,v.status))throw Error('Readiness reference changed.');return Object.fromEntries(['proposalId','firstReviewId','submissionVersion','title','roles','status'].map(k=>[k,v[k]]))}
function resetTeamApprovalClient(){teamApprovalQueue=null;teamApprovalQueueGeneration++;teamApprovalDetailGeneration++;if(teamApprovalLock){teamApprovalLock=null;lockShared(false)}if(document.querySelector('#team-approval-detail')&&$('#modal').open)closeModal()}
function currentTeamApprovalQueue(){return teamApprovalQueue&&intakeMentorClientCurrent(teamApprovalQueue.context)?teamApprovalQueue:null}
async function refreshTeamApprovalQueue(offset=0){
 if(!sharedReady||db.intakeTeamAccess?.enabled!==true)return resetTeamApprovalClient();const c=intakeMentorClientContext(),generation=++teamApprovalQueueGeneration;teamApprovalQueue=null;
 try{const r=await sharedFetch('/api/workspace',{command:'readIntakeTeamApprovalQueue',actor:c.actor,revision:c.revision,args:[{offset,limit:20}],context:{page:'Activity Intake'}});if(generation!==teamApprovalQueueGeneration||!intakeMentorClientCurrent(c))return;intakeMentorClientProtocol(r,c,'APPROVAL_QUEUE');const q=r.readiness;
  if(!q||!Array.isArray(q.items)||!Number.isSafeInteger(q.total)||q.total<0||q.offset!==offset||q.limit!==20||q.items.length!==Math.min(20,Math.max(0,q.total-offset)))throw Error('Readiness page changed.');const items=q.items.map(teamApprovalItem);if(new Set(items.map(x=>x.proposalId)).size!==items.length)throw Error('Duplicate readiness references.');teamApprovalQueue={context:c,items,total:q.total,offset};if(['Overview','Activity Intake'].includes(page))render();
 }catch(e){if(generation===teamApprovalQueueGeneration&&intakeMentorClientCurrent(c)){teamApprovalQueue=null;if(e.status!==503)toast('Readiness access changed. Refresh the workspace.');if(['Overview','Activity Intake'].includes(page))render()}}
}
function teamApprovalPanel(){const q=currentTeamApprovalQueue();return q?.total?`<section class="panel"><h2>Project review readiness</h2><p>Reviewed team proposals within your coordination or final review authority.</p>${tableHTML(['Proposal','Your role','Readiness','Details'],q.items.map((x,i)=>[esc(x.title),x.roles.map(r=>r==='COORDINATOR'?'Coordinator':'Final reviewer').join(', '),teamApprovalStates[x.status],`<button type="button" data-team-approval-open="${i}">Review readiness</button>`]))}<p>${q.items.length?q.offset+1:0}–${Math.min(q.offset+q.items.length,q.total)} of ${q.total}</p>${q.offset?'<button type="button" data-team-approval-page="'+Math.max(0,q.offset-20)+'">Previous</button>':''}${q.offset+20<q.total&&q.offset+20<=10000?'<button type="button" data-team-approval-page="'+(q.offset+20)+'">Next</button>':''}<button type="button" data-team-approval-page="0">Refresh readiness</button></section>`:''}
function teamApprovalDetail(v){
 const item=teamApprovalItem(v),final=cleanTeamFinalDecision(v),q=v.consultation,names=['requested','accepted','declined','withdrawn','stale'];if(!Object.hasOwn(teamApprovalMentors,v.mentorStatus)||!q||typeof q.required!=='boolean'||(q.required?typeof q.scopeConfirmed!=='boolean':q.scopeConfirmed!==null)||!Number.isSafeInteger(q.totalIssued)||q.totalIssued<0||!names.every(k=>Number.isSafeInteger(q[k])&&q[k]>=0)||names.reduce((sum,k)=>sum+q[k],0)!==q.totalIssued||!v.finalAuthority||typeof v.finalAuthority.role!=='string'||!/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(v.finalAuthority.role)||typeof v.finalAuthority.available!=='boolean'||!Array.isArray(v.issues)||new Set(v.issues).size!==v.issues.length||!v.issues.every(k=>Object.hasOwn(teamApprovalIssues,k))||(q.required&&q.scopeConfirmed===v.issues.includes('CONSULTATION_SCOPE_UNCONFIRMED'))||v.status!==(final?'FINAL_'+final.decision:v.issues.length?'REVIEW_REQUIRED':'READY_FOR_FINAL_REVIEW')||v.canApprove!==false||v.approvalRecorded!==(final?.decision==='APPROVED')||v.executionAuthorized!==false)throw Error('Readiness details changed.');
 return `<section id="team-approval-detail"><h2>${esc(item.title)}</h2><p>${esc(item.proposalId)} · submission v${item.submissionVersion}</p><h3>${teamApprovalStates[item.status]}</h3><p>Mentor: ${esc(teamApprovalMentors[v.mentorStatus])}</p><p>Configured final approval role: ${esc(v.finalAuthority.role)} · ${v.finalAuthority.available?'Available':'Unavailable'}</p><h3>Consultation responsibilities</h3><p>${q.required?(q.scopeConfirmed?'Research consultation scope is confirmed for the current requests.':'Research consultation scope requires coordinator confirmation.'):'Research consultation scope is not required for this academic route.'}</p>${tableHTML(['Latest requests','Pending','Accepted','Declined','Withdrawn','Source changed'],[[q.totalIssued,q.requested,q.accepted,q.declined,q.withdrawn,q.stale]])}${v.issues.length?'<h3>Items needing attention</h3><ul>'+v.issues.map(k=>'<li>'+esc(teamApprovalIssues[k])+'</li>').join('')+'</ul>':''}${final?'<h3>Recorded final decision</h3><p>'+esc(final.reason)+'</p><p>Permission to start requires the separate controlled activity handoff and existing workflow.</p>':'<p>This readiness review does not record final approval or permission to start. Department acceptance confirms supporting responsibility; delivery and overall consultation completion remain separate.</p>'}</section>`;
}
async function openTeamApprovalDetail(index){
 const q=currentTeamApprovalQueue();if(!q||sharedBusy||!Number.isSafeInteger(index)||!q.items[index])return;const c=q.context,item=q.items[index],generation=++teamApprovalDetailGeneration,token={};teamApprovalLock=token;modal('<section id="team-approval-detail"><h2>Checking readiness…</h2></section>');const marker=document.querySelector('#team-approval-detail');lockShared(true);
 try{const r=await sharedFetch('/api/workspace',{command:'readIntakeTeamApprovalReadiness',actor:c.actor,revision:c.revision,args:[{proposalId:item.proposalId}],context:{page:'Activity Intake'}});if(generation!==teamApprovalDetailGeneration||!intakeMentorClientCurrent(c)||currentTeamApprovalQueue()!==q||!$('#modal').open||document.querySelector('#team-approval-detail')!==marker)return;intakeMentorClientProtocol(r,c,'APPROVAL_READINESS');const fresh=teamApprovalItem(r.readiness);if(['proposalId','firstReviewId','submissionVersion'].some(k=>fresh[k]!==item[k])||JSON.stringify(fresh.roles)!==JSON.stringify(item.roles))throw Error('Readiness reference changed.');modal(teamApprovalDetail(r.readiness));if(typeof bindTeamScopePreview==='function')bindTeamScopePreview(r.readiness,{context:c,queue:q,item:fresh,marker:document.querySelector('#team-approval-detail')});if(typeof bindTeamFinalPreview==='function')bindTeamFinalPreview(r.readiness,{context:c,queue:q,item:fresh,marker:document.querySelector('#team-approval-detail')});if(typeof bindTeamHandoffAction==='function')bindTeamHandoffAction(r.readiness,{context:c,queue:q,item:fresh,marker:document.querySelector('#team-approval-detail')});if(typeof bindTeamStartAction==='function')bindTeamStartAction(r.readiness,{context:c,queue:q,item:fresh,marker:document.querySelector('#team-approval-detail')});
 }catch(e){if(generation===teamApprovalDetailGeneration&&intakeMentorClientCurrent(c)){closeModal();resetTeamApprovalClient();toast('Readiness changed. Refresh and reopen the proposal.')}}finally{if(teamApprovalLock===token){teamApprovalLock=null;lockShared(false)}}
}
const approvalPriorRefresh=refreshIntakeTeamAccess;refreshIntakeTeamAccess=async function(){resetTeamApprovalClient();await approvalPriorRefresh();if(sharedReady&&db.intakeTeamAccess?.enabled===true)await refreshTeamApprovalQueue()};
const approvalPriorReset=resetIntakeTeamClient;resetIntakeTeamClient=function(){resetTeamApprovalClient();return approvalPriorReset()};
const approvalPriorOverview=overview;overview=function(){const q=currentTeamApprovalQueue();return approvalPriorOverview()+(q?.total?`<section class="panel"><h2>Project review readiness</h2><p>${q.total} reviewed team proposal${q.total===1?'':'s'} within your authority.</p>${btn('Open module overview',"go('Activity Intake')")}</section>`:'')};
const approvalPriorIntakes=activityIntakesPage;activityIntakesPage=function(){return teamApprovalPanel()+approvalPriorIntakes()};
document.addEventListener('click',event=>{const b=event.target.closest?.('[data-team-approval-open]');if(b){openTeamApprovalDetail(Number(b.dataset.teamApprovalOpen));return}const p=event.target.closest?.('[data-team-approval-page]');if(p&&!sharedBusy){const offset=Number(p.dataset.teamApprovalPage);if(Number.isSafeInteger(offset)&&offset>=0&&offset<=10000)refreshTeamApprovalQueue(offset)}});
